# Runs benchmark programs that were built by build_prebuilt.ps1, on a computer without any tools (Windows PowerShell is enough). Every folder next to
# this script that holds .exe files is one build (baseline, candidate, ...). The scenes and their settings are those of history.py (small, windowed),
# the programs run in turns (build A, build B, A, B, ...) so that drift of the computer hits both the same.
#   powershell -File run_prebuilt.ps1 [-Runs 3] [-Frames <override>]
# The result is written to results.txt and printed: the mean and the spread of every value, per scene and build.
param([int] $Runs = 3, [int] $Frames = 0)
$ErrorActionPreference = "Stop"
$root = Split-Path -Parent $MyInvocation.MyCommand.Path
$scenes = [ordered]@{
    "flythrough" = @{ env = @{ BENCH_OBJECTS = "5000"; BENCH_FRAMES = "100"; BENCH_W = "320"; BENCH_H = "180" }; keys = "ms_avg", "tris", "draws" }
    "waterfall"  = @{ env = @{ BENCH_SPRITES = "2000"; BENCH_FRAMES = "100"; BENCH_W = "320"; BENCH_H = "180" }; keys = "ms_avg", "update_ms", "draws" }
    "dungeon"    = @{ env = @{ BENCH_FRAMES = "100"; BENCH_W = "320"; BENCH_H = "180" }; keys = "ms_avg", "update_ms", "draws" }
    "forest"     = @{ env = @{ BENCH_FRAMES = "200"; BENCH_W = "640"; BENCH_H = "360" }; keys = "ms_avg" }
    "emitted"    = @{ env = @{}; keys = $null }
}
$builds = Get-ChildItem $root -Directory | Where-Object { Test-Path (Join-Path $_.FullName "emitted.exe") }
$values = @{}
$temp = Join-Path $env:TEMP ("bench-run-" + [guid]::NewGuid())
New-Item -ItemType Directory -Force $temp | Out-Null
for ($run = 1; $run -le $Runs; $run++) {
    foreach ($scene in $scenes.Keys) {
        foreach ($build in $builds) {
            $resultFile = Join-Path $temp "result.txt"
            Remove-Item $resultFile -ErrorAction SilentlyContinue
            $saved = @{}
            $settings = @{} + $scenes[$scene].env + @{ BENCH_RESULT = $resultFile; BENCH_SEED = "1" }
            if ($Frames -gt 0 -and $settings.ContainsKey("BENCH_FRAMES")) { $settings.BENCH_FRAMES = [string]$Frames }
            foreach ($key in $settings.Keys) { $saved[$key] = [Environment]::GetEnvironmentVariable($key); [Environment]::SetEnvironmentVariable($key, $settings[$key]) }
            Write-Host ("run {0}: {1} {2}" -f $run, $build.Name, $scene)
            $process = Start-Process -FilePath (Join-Path $build.FullName "$scene.exe") -WorkingDirectory $temp -Wait -PassThru
            foreach ($key in $settings.Keys) { [Environment]::SetEnvironmentVariable($key, $saved[$key]) }
            if (-not (Test-Path $resultFile)) { Write-Host "  no result (exit code $($process.ExitCode))"; continue }
            $line = (Get-Content $resultFile | Where-Object { $_ -match "RESULT " } | Select-Object -First 1)
            foreach ($match in [regex]::Matches($line.Substring($line.IndexOf("RESULT ") + 7), "(\w+)=([-+\d.eE]+)")) {
                $key = $match.Groups[1].Value
                if ($scenes[$scene].keys -and $scenes[$scene].keys -notcontains $key) { continue }
                $id = "$scene|$key|$($build.Name)"
                if (-not $values.ContainsKey($id)) { $values[$id] = New-Object System.Collections.ArrayList }
                [void]$values[$id].Add([double]::Parse($match.Groups[2].Value, [Globalization.CultureInfo]::InvariantCulture))
            }
        }
    }
}
$lines = @("machine: $env:COMPUTERNAME, $((Get-CimInstance Win32_Processor | Select-Object -First 1).Name), $((Get-CimInstance Win32_VideoController | Select-Object -First 1).Name), $((Get-CimInstance Win32_OperatingSystem).Caption)", "runs: $Runs", "scene|value|build|mean|stdev|runs")
foreach ($id in ($values.Keys | Sort-Object)) {
    $v = $values[$id].ToArray()
    $mean = ($v | Measure-Object -Average).Average
    $stdev = if ($v.Count -gt 1) { [math]::Sqrt((($v | ForEach-Object { ($_ - $mean) * ($_ - $mean) } | Measure-Object -Sum).Sum) / ($v.Count - 1)) } else { 0 }
    $lines += ("{0}|{1:G6}|{2:G4}|{3}" -f $id, $mean, $stdev, ($v -join ","))
}
$lines | Out-File (Join-Path $root "results.txt") -Encoding utf8
$lines | ForEach-Object { Write-Host $_ }
Remove-Item -Recurse -Force $temp
